{
  "summary": "Implement the triage.sh script to group ERROR log lines by signature, count occurrences, and output 'count signature' format, excluding non-ERROR lines like INFO/WARN.",
  "files": [
    {
      "path": "scripts/triage.sh",
      "content": "#!/usr/bin/env bash
set -euo pipefail

if [[ $# -ne 1 ]]; then
  echo "Usage: $0 <logfile>" >&2
  exit 1
fi

logfile="$1"

# Extract ERROR lines, remove timestamp and level, group by signature, count, sort by count desc
awk '
  $2 == "ERROR" {
    # Rebuild signature from field 3 onwards
    sig = ""
    for (i = 3; i <= NF; i++) {
      if (sig != "") sig = sig " "
      sig = sig $i
    }
    count[sig]++
  }
  END {
    for (sig in count) {
      print count[sig], sig
    }
  }
' "$logfile" | sort -rn -k1,1
"
    }
  ]
}
